import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.F7eQ-ohH.js";const c=JSON.parse('{"title":"马克思主义基本原理","description":"","frontmatter":{},"headers":[],"relativePath":"行测/基本常识/2.政治常识.md","filePath":"行测/基本常识/2.政治常识.md","lastUpdated":1788883925000}'),p={name:"行测/基本常识/2.政治常识.md"};function r(e,l,d,h,s,n){return i(),a("div",null,[...l[0]||(l[0]=[o('<h1 id="马克思主义基本原理" tabindex="-1">马克思主义基本原理 <a class="header-anchor" href="#马克思主义基本原理" aria-label="Permalink to &quot;马克思主义基本原理&quot;">​</a></h1><h2 id="马克思主义哲学-高频考点" tabindex="-1">马克思主义哲学（高频考点） <a class="header-anchor" href="#马克思主义哲学-高频考点" aria-label="Permalink to &quot;马克思主义哲学（高频考点）&quot;">​</a></h2><ol><li>唯物论</li></ol><ul><li>核心原理：世界物质统一性原理（物质是本原，意识是派生）、物质与意识的辩证关系（物质决定意识，意识对物质具有能动反作用）。</li><li>高频考点：客观规律性与主观能动性的统一（如 “量力而行与尽力而为” 的哲学依据）。</li></ul><ol start="2"><li>辩证法</li></ol><ul><li>三大规律：对立统一规律（矛盾分析法，重中之重，如主要矛盾与次要矛盾、矛盾的主要方面与次要方面）、质量互变规律（量变是质变的前提，质变是量变的必然结果）、否定之否定规律（事物发展是前进性与曲折性的统一）。</li><li>基本范畴：原因与结果、必然与偶然、现象与本质。</li></ul><ol start="3"><li>认识论</li></ol><ul><li>核心关系：实践对认识的决定作用（实践是认识的来源、发展动力、检验标准、目的），认识的辩证发展过程（感性认识→理性认识→实践的飞跃）。</li><li>真理特性：客观性（真理的本质属性）、相对性（真理是具体的、有条件的）。</li></ul><ol start="4"><li>历史唯物主义</li></ol><ul><li>核心原理：社会存在决定社会意识（社会存在的性质决定社会意识的性质，社会存在的变化决定社会意识的变化）、社会基本矛盾（生产力与生产关系、经济基础与上层建筑的矛盾，是社会发展的根本动力）。</li><li>重要论断：人民群众是历史的创造者（物质财富、精神财富的创造者，社会变革的决定力量）。</li></ul><h2 id="马克思主义政治经济学" tabindex="-1">马克思主义政治经济学 <a class="header-anchor" href="#马克思主义政治经济学" aria-label="Permalink to &quot;马克思主义政治经济学&quot;">​</a></h2><ol><li>商品与货币</li></ol><ul><li>商品二因素：使用价值（商品的有用性，自然属性）与价值（凝结在商品中的无差别人类劳动，社会属性）。</li><li>劳动二重性：具体劳动（创造使用价值）与抽象劳动（形成价值）。</li><li>价值规律：表现形式是商品价格围绕价值上下波动，作用是调节生产资料和劳动力在社会各部门的分配。</li></ul><ol start="2"><li>剩余价值</li></ol><ul><li>本质：剩余价值是由雇佣工人创造的、被资本家无偿占有的、超过劳动力价值的价值。</li><li>生产方法：绝对剩余价值生产（延长工作日）、相对剩余价值生产（提高劳动生产率）。</li></ul><ol start="3"><li>资本主义基本矛盾</li></ol><ul><li>核心矛盾：生产社会化与生产资料资本主义私人占有之间的矛盾。</li><li>必然结果：导致资本主义经济危机周期性爆发。</li></ul><h1 id="中国特色社会主义理论体系" tabindex="-1">中国特色社会主义理论体系 <a class="header-anchor" href="#中国特色社会主义理论体系" aria-label="Permalink to &quot;中国特色社会主义理论体系&quot;">​</a></h1><h2 id="理论发展脉络-一脉相承、与时俱进" tabindex="-1">理论发展脉络（一脉相承、与时俱进） <a class="header-anchor" href="#理论发展脉络-一脉相承、与时俱进" aria-label="Permalink to &quot;理论发展脉络（一脉相承、与时俱进）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>理论成果</th><th>核心问题</th><th>关键贡献</th></tr></thead><tbody><tr><td>邓小平理论</td><td>什么是社会主义、怎样建设社会主义</td><td>开创中国特色社会主义道路，提出改革开放、社会主义市场经济等重要思想</td></tr><tr><td>“三个代表” 重要思想</td><td>建设什么样的党、怎样建设党</td><td>提出 “始终代表中国先进生产力的发展要求、先进文化的前进方向、最广大人民的根本利益”，本质是立党为公、执政为民</td></tr><tr><td>科学发展观</td><td>实现什么样的发展、怎样发展</td><td>第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾</td></tr></tbody></table><h2 id="习近平新时代中国特色社会主义思想-绝对核心" tabindex="-1">习近平新时代中国特色社会主义思想（绝对核心） <a class="header-anchor" href="#习近平新时代中国特色社会主义思想-绝对核心" aria-label="Permalink to &quot;习近平新时代中国特色社会主义思想（绝对核心）&quot;">​</a></h2><ol><li>历史方位：中国特色社会主义进入新时代（我国社会主要矛盾转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾）。</li><li>核心内容：</li></ol><ul><li>“十个明确”：明确新时代坚持和发展中国特色社会主义的总目标、总任务、总体布局等基本问题（如明确中国特色社会主义最本质的特征是中国共产党领导）。</li><li>“十四个坚持”：新时代坚持和发展中国特色社会主义的基本方略（如坚持党对一切工作的领导、坚持以人民为中心）。</li></ul><ol><li>实践部署：</li></ol><ul><li>总体布局：“五位一体”（经济建设、政治建设、文化建设、社会建设、生态文明建设）。</li><li>战略布局：“四个全面”（全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党）。</li><li>发展理念：新发展理念（创新、协调、绿色、开放、共享）。</li></ul><ol start="2"><li>重大论断：人类命运共同体、总体国家安全观、中国式现代化（人口规模巨大、全体人民共同富裕、物质文明和精神文明相协调、人与自然和谐共生、走和平发展道路）。</li></ol><h1 id="党和国家重大方针政策" tabindex="-1">党和国家重大方针政策 <a class="header-anchor" href="#党和国家重大方针政策" aria-label="Permalink to &quot;党和国家重大方针政策&quot;">​</a></h1><ol><li>最新党代会报告（党的二十大核心要点）</li></ol><ul><li>中心任务：团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴。</li><li>战略部署：加快构建新发展格局、实施科教兴国战略、发展全过程人民民主、推进共同富裕等。</li></ul><ol start="2"><li>重要会议精神</li></ol><ul><li>中央经济工作会议：每年定调下一年经济工作总基调（如 “稳中求进”），部署重点任务（如扩大内需、深化供给侧结构性改革）。</li><li>中央一号文件：聚焦 “三农” 工作，核心部署乡村振兴、粮食安全、农民增收等重点任务。</li></ul><ol start="3"><li>治国理政新理念新思想新战略</li></ol><ul><li>核心要义：坚持和加强党的全面领导、坚持以人民为中心的发展思想、坚持统筹发展和安全。</li></ul><h1 id="四、党史、新中国史、改革开放史、社会主义发展史" tabindex="-1">四、党史、新中国史、改革开放史、社会主义发展史 <a class="header-anchor" href="#四、党史、新中国史、改革开放史、社会主义发展史" aria-label="Permalink to &quot;四、党史、新中国史、改革开放史、社会主义发展史&quot;">​</a></h1><h2 id="重要历史事件与时间节点" tabindex="-1">重要历史事件与时间节点 <a class="header-anchor" href="#重要历史事件与时间节点" aria-label="Permalink to &quot;重要历史事件与时间节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>事件</th><th>历史意义</th></tr></thead><tbody><tr><td>1921 年</td><td>中国共产党成立（一大）</td><td>中国革命的面貌焕然一新</td></tr><tr><td>1935 年</td><td>遵义会议</td><td>挽救了党、挽救了红军、挽救了中国革命，是生死攸关的转折点</td></tr><tr><td>1978 年</td><td>十一届三中全会</td><td>作出改革开放的历史性决策，开启中国特色社会主义新时期</td></tr><tr><td>2017 年</td><td>党的十九大召开</td><td>宣告中国特色社会主义进入新时代</td></tr><tr><td>2022 年</td><td>党的二十大召开</td><td>擘画全面建设社会主义现代化国家宏伟蓝图</td></tr></tbody></table><h2 id="党的重要会议关键内容" tabindex="-1">党的重要会议关键内容 <a class="header-anchor" href="#党的重要会议关键内容" aria-label="Permalink to &quot;党的重要会议关键内容&quot;">​</a></h2><ul><li>一大（1921）：确定党的名称为 “中国共产党”，明确奋斗目标是推翻资产阶级政权，建立无产阶级专政。</li><li>七大（1945）：确立毛泽东思想为党的指导思想，为抗战胜利和全国解放奠定基础。</li><li>十五大（1997）：确立邓小平理论为党的指导思想。</li><li>十六大（2002）：确立 “三个代表” 重要思想为党的指导思想。</li><li>十八大（2012）：确立科学发展观为党的指导思想，明确全面建成小康社会目标。</li><li>十九大（2017）：确立习近平新时代中国特色社会主义思想为党的指导思想。</li><li>二十大（2022）：对全面建设社会主义现代化国家、全面推进中华民族伟大复兴作出战略部署。</li></ul><h2 id="伟大精神谱系" tabindex="-1">伟大精神谱系 <a class="header-anchor" href="#伟大精神谱系" aria-label="Permalink to &quot;伟大精神谱系&quot;">​</a></h2><ul><li>建党精神：坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民（精神之源）。</li><li>重要精神：长征精神（不怕牺牲、排除万难）、改革开放精神（敢闯敢试、敢为人先）、脱贫攻坚精神（上下同心、尽锐出战）、抗疫精神（生命至上、举国同心）。</li></ul><h1 id="第二部分-政治常识笔试题-含解析" tabindex="-1">第二部分：政治常识笔试题（含解析） <a class="header-anchor" href="#第二部分-政治常识笔试题-含解析" aria-label="Permalink to &quot;第二部分：政治常识笔试题（含解析）&quot;">​</a></h1><p>10 题）</p><ol><li>下列关于矛盾分析法的说法，错误的是（ ）</li></ol><p>A. 主要矛盾决定事物的发展方向</p><p>B. 矛盾的主要方面决定事物的性质</p><p>C. 矛盾双方在一定条件下可以相互转化</p><p>D. 矛盾的斗争性是事物发展的根本动力</p><ol start="2"><li>马克思主义政治经济学中，商品的价值是由（ ）决定的</li></ol><p>A. 商品的使用价值</p><p>B. 生产商品的社会必要劳动时间</p><p>C. 商品的供求关系</p><p>D. 商品的价格</p><ol start="3"><li>邓小平理论的核心问题是（ ）</li></ol><p>A. 建设什么样的党、怎样建设党</p><p>B. 实现什么样的发展、怎样发展</p><p>C. 什么是社会主义、怎样建设社会主义</p><p>D. 新时代坚持和发展什么样的中国特色社会主义</p><ol start="4"><li>中国特色社会主义进入新时代，我国社会的主要矛盾是（ ）</li></ol><p>A. 人民日益增长的物质文化需要同落后的社会生产之间的矛盾</p><p>B. 人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾</p><p>C. 生产力与生产关系、经济基础与上层建筑之间的矛盾</p><p>D. 阶级矛盾和阶级斗争</p><ol start="5"><li>党的二十大报告指出，全面建设社会主义现代化国家的首要任务是（ ）</li></ol><p>A. 全面从严治党</p><p>B. 高质量发展</p><p>C. 共同富裕</p><p>D. 科技创新</p><ol start="6"><li>下列会议中，确立毛泽东思想为党的指导思想的是（ ）</li></ol><p>A. 遵义会议</p><p>B. 党的七大</p><p>C. 党的十五大</p><p>D. 党的十八大</p><ol start="7"><li>新发展理念中，“引领发展的第一动力” 是（ ）</li></ol><p>A. 协调</p><p>B. 绿色</p><p>C. 创新</p><p>D. 共享</p><ol start="8"><li>历史唯物主义认为，社会发展的根本动力是（ ）</li></ol><p>A. 人民群众的实践活动</p><p>B. 社会基本矛盾运动</p><p>C. 阶级斗争</p><p>D. 科学技术的进步</p><ol start="9"><li>“三个代表” 重要思想的本质是（ ）</li></ol><p>A. 坚持党的先进性</p><p>B. 立党为公、执政为民</p><p>C. 与时俱进</p><p>D. 解放思想、实事求是</p><ol start="10"><li>下列不属于 “四个全面” 战略布局新表述的是（ ）</li></ol><p>A. 全面建设社会主义现代化国家</p><p>B. 全面深化改革</p><p>C. 全面建设小康社会</p><p>D. 全面从严治党</p><p>5 题）</p><ol start="11"><li>下列属于马克思主义哲学辩证法三大规律的有（ ）</li></ol><p>A. 对立统一规律</p><p>B. 质量互变规律</p><p>C. 否定之否定规律</p><p>D. 因果规律</p><ol start="12"><li>习近平新时代中国特色社会主义思想的核心内容包括（ ）</li></ol><p>A. “十个明确”</p><p>B. “十四个坚持”</p><p>C. “五位一体” 总体布局</p><p>D. 新发展理念</p><ol start="13"><li>下列属于党的伟大精神谱系的有（ ）</li></ol><p>A. 建党精神</p><p>B. 长征精神</p><p>C. 改革开放精神</p><p>D. 脱贫攻坚精神</p><ol start="14"><li>下列关于党的重要会议的说法，正确的有（ ）</li></ol><p>A. 十一届三中全会作出改革开放的历史性决策</p><p>B. 党的十九大宣告中国特色社会主义进入新时代</p><p>C. 党的二十大确立习近平新时代中国特色社会主义思想为党的指导思想</p><p>D. 党的一大确定党的奋斗目标是推翻资产阶级政权</p><ol start="15"><li>下列属于党和国家重大方针政策的有（ ）</li></ol><p>A. 乡村振兴战略</p><p>B. 科教兴国战略</p><p>C. 总体国家安全观</p><p>D. 人类命运共同体理念</p><h1 id="答案与解析" tabindex="-1">答案与解析 <a class="header-anchor" href="#答案与解析" aria-label="Permalink to &quot;答案与解析&quot;">​</a></h1><h2 id="单项选择题" tabindex="-1">单项选择题 <a class="header-anchor" href="#单项选择题" aria-label="Permalink to &quot;单项选择题&quot;">​</a></h2><ol><li>答案：D</li></ol><p>解析：矛盾是事物发展的根本动力，矛盾的同一性和斗争性共同推动事物的发展，而非单纯的斗争性。A、B、C 均为矛盾分析法的正确表述。</p><ol start="2"><li>答案：B</li></ol><p>解析：商品的价值由生产商品的社会必要劳动时间决定，社会必要劳动时间越长，商品价值量越大。使用价值是自然属性（A 错误），供求关系影响价格（C 错误），价格是价值的货币表现（D 错误）。</p><ol start="3"><li>答案：C</li></ol><p>解析：邓小平理论围绕 “什么是社会主义、怎样建设社会主义” 展开；A 是 “三个代表” 重要思想的核心问题；B 是科学发展观的核心问题；D 是习近平新时代中国特色社会主义思想的核心问题。</p><ol start="4"><li>答案：B</li></ol><p>解析：党的十九大明确我国社会主要矛盾转化为 “人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾”；A 是改革开放以来至新时代前的主要矛盾；C 是社会发展的基本矛盾；D 在我国已不是社会主要矛盾。</p><ol start="5"><li>答案：B</li></ol><p>解析：党的二十大报告指出，高质量发展是全面建设社会主义现代化国家的首要任务；A 是 “四个全面” 的重要内容；C 是社会主义的本质要求；D 是高质量发展的战略支撑。</p><ol start="6"><li>答案：B</li></ol><p>解析：党的七大（1945 年）确立毛泽东思想为党的指导思想；遵义会议（1935 年）确立了毛泽东同志在党中央和红军的领导地位；十五大（1997 年）确立邓小平理论为指导思想；十八大（2012 年）确立科学发展观为指导思想。</p><ol start="7"><li>答案：C</li></ol><p>解析：新发展理念中，创新是引领发展的第一动力，协调是内在要求，绿色是必要条件，开放是必由之路，共享是本质要求。</p><ol start="8"><li>答案：B</li></ol><p>解析：历史唯物主义认为，社会基本矛盾（生产力与生产关系、经济基础与上层建筑）的运动是社会发展的根本动力；A 是社会发展的决定力量；C 是阶级社会发展的直接动力；D 是重要动力。</p><ol start="9"><li>答案：B</li></ol><p>解析：“三个代表” 重要思想的本质是立党为公、执政为民，核心是坚持党的先进性，精髓是解放思想、实事求是、与时俱进。</p><ol start="10"><li>答案：C</li></ol><p>解析：“四个全面” 战略布局新表述为：全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党；“全面建设小康社会” 是旧表述（已完成）。</p><h1 id="多项选择题" tabindex="-1">多项选择题 <a class="header-anchor" href="#多项选择题" aria-label="Permalink to &quot;多项选择题&quot;">​</a></h1><ol start="11"><li>答案：ABC</li></ol><p>解析：辩证法三大规律是对立统一规律、质量互变规律、否定之否定规律；因果规律是辩证法的基本范畴，并非三大规律。</p><ol start="12"><li>答案：AB</li></ol><p>解析：习近平新时代中国特色社会主义思想的核心内容是 “十个明确” 和 “十四个坚持”；C、D 是其重要实践部署，并非核心内容的直接构成。</p><ol start="13"><li>答案：ABCD</li></ol><p>解析：建党精神是精神之源，长征精神、改革开放精神、脱贫攻坚精神均属于伟大精神谱系的重要组成部分，此外还包括抗疫精神、航天精神等。</p><ol start="14"><li>答案：ABD</li></ol><p>解析：C 错误，习近平新时代中国特色社会主义思想于党的十九大确立为党的指导思想；A、B、D 表述均正确。</p><ol start="15"><li>答案：ABCD</li></ol><p>解析：乡村振兴战略、科教兴国战略是国家重大发展战略，总体国家安全观是治国理政重要理念，人类命运共同体是外交领域重大倡议，均属于党和国家重大方针政策。</p>',151)])])}const b=t(p,[["render",r]]);export{c as __pageData,b as default};
